    explanation: '中性線電流は各相電流のベクトル（フェーザ）和であり、位相を無視した単純な算術和ではない。平衡時は打ち消し合い0となる。\n【図解】Y結線4線式の中性線電流\n　★重要：IN＝Ia＋Ib＋Ic（ベクトル和）\n　○補足：平衡負荷なら3相が120°ずつずれて打ち消し合いIN＝0\n　×誤りやすい点：算術和（|Ia|＋|Ib|＋|Ic|）と混同しやすい\n　→結論：位相を考慮したベクトル和で計算する必要がある。',
