    explanation: 'F行列（ABCD定数）は電流の基準方向の定義に依存する表現であり、電流の向きの取り方を変えると行列の値（符号を含む）も変わりうる。定義を明確にして扱う必要がある。\n【図解】二端子対網（F行列）\n　★重要：縦続接続の合成F行列＝各F行列の積\n　○補足：可逆な回路網ではAD−BC＝1が成り立つ\n　×誤りやすい点：「電流の向きによらず同一行列」という誤解\n　→結論：F行列は電流の基準方向の定義に依存するため注意が必要。',
