    correctKey: 'D',
    explanation: 'IPコードは固形物・水の浸入に対する保護等級を示す指標であり、絶縁階級や絶縁抵抗の良否を直接示すものではない。両者は異なる規格・目的の指標である。\n【図解】IPコード（保護等級）\n　★重要：IP□□の1桁目＝固形物保護等級、2桁目＝水侵入保護等級\n　○補足：数字が大きいほど保護性能が高い（例：IP44、IP65等）\n　×誤りやすい点：IPコードと絶縁階級（耐熱クラス）を混同しやすい\n　→結論：IPコードは「浸入物に対する保護」の指標であり、絶縁性能の指標ではない。',
