    question: 'V2H（ビークル・トゥ・ホーム）システムに関する記述として、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: 'V2Hシステムは、電気自動車（EV）等に搭載されたバッテリーに蓄えられた電力を、専用の機器（V2H機器）を介して住宅側へ供給できるようにするシステムである。', explanation: '適当。V2Hシステムの基本的な機能である。' },
      { key: 'B', text: 'V2Hシステムは、停電時にEVのバッテリーを非常用電源として活用できる利点がある。', explanation: '適当。V2Hの停電対策上の利点である。' },
      { key: 'C', text: 'V2Hシステムでは、EVのバッテリーに蓄えられた直流電力を、住宅内で利用可能な交流電力に変換するため、V2H機器内にインバータ（直流‐交流変換装置）が組み込まれている。', explanation: '適当。V2H機器の構成要素である。' },
      { key: 'D', text: 'V2Hシステムは、EVから住宅側への一方向の電力供給のみを行う仕組みであり、住宅側の電力（太陽光発電の余剰電力等）でEVを充電する機能は技術的に実現不可能である。', explanation: '不適当。V2Hシステムは住宅側からEVへの充電と、EVから住宅側への電力供給（放電）の双方向の電力融通を可能とする機器が一般的であり、「一方向のみ」「充電機能は技術的に実現不可能」は誤りである。' },
    ],
    correctKey: 'D',
    explanation: 'V2Hシステムは、住宅からEVへの充電と、EVから住宅への電力供給の双方向の電力融通を可能とする機器が一般的である。「一方向のみで充電は不可能」は誤りである。\n【図解】V2Hシステム\n　★重要：EVバッテリー⇔住宅間で双方向の電力融通が可能\n　○補足：V2H機器内蔵のインバータで直流（バッテリー）⇔交流（住宅）を変換\n　×誤りやすい点：「一方向（放電専用）」という誤解\n　→結論：V2Hは充電・放電双方向に対応するのが一般的である。',
