    choices: [
      { key: 'A', text: '負荷試験は、非常用発電設備が実際の負荷（またはそれに相当する模擬負荷）を接続した状態で、定格出力を発揮できるかを確認する試験である。', explanation: '適当。負荷試験の基本的な目的である。' },
      { key: 'B', text: '負荷試験には、実際の建物負荷を用いて行う「実負荷試験」と、模擬負荷（負荷試験装置）を用いて行う「疑似負荷試験」がある。', explanation: '適当。負荷試験の種類である。' },
      { key: 'C', text: '負荷試験を定期的に実施することは、発電機・エンジン等が実際の非常時に確実に定格性能を発揮できることを確認するための重要な保守点検項目の一つである。', explanation: '適当。負荷試験の実務上の重要性である。' },
      { key: 'D', text: '負荷試験は、発電設備の無負荷運転（起動確認）のみで代替可能であり、実際に負荷を接続した状態での性能確認は保守点検上不要である。', explanation: '不適当。無負荷運転（起動確認）のみでは、実際に負荷を接続した状態で定格出力を継続して発揮できるかどうかを十分に確認することはできない。負荷試験は無負荷運転では代替できない重要な点検項目である。' },
    ],
    correctKey: 'D',
    explanation: '無負荷運転（起動確認）のみでは、実際に負荷を接続した状態での定格出力の継続的な発揮能力（排気温度・出力安定性等）を確認できない。負荷試験は無負荷運転では代替できない重要な点検項目である。\n【図解】非常用発電設備の負荷試験\n　★重要：実負荷試験・疑似負荷試験のいずれかで定格出力発揮能力を確認\n　○補足：定期的な負荷試験は非常時の確実な性能発揮を保証する重要点検\n　×誤りやすい点：「無負荷運転だけで十分」という誤解\n　→結論：負荷試験は無負荷運転では代替できない必須の保守点検項目。',
    difficulty: 'standard',
