    choices: [
      { key: 'A', text: 'エポキシ樹脂は、優れた電気絶縁性・機械的強度・耐薬品性を持つ熱硬化性樹脂であり、モールド変圧器の巻線の固定・絶縁等に用いられる。', explanation: '適当。エポキシ樹脂の基本的な性質・用途である。' },
      { key: 'B', text: 'エポキシ樹脂は、絶縁油を使用しないモールド変圧器において、絶縁油に代わる主要な絶縁材料としての役割を担っている。', explanation: '適当。モールド変圧器におけるエポキシ樹脂の役割である。' },
      { key: 'C', text: 'エポキシ樹脂に無機フィラー（シリカ粉等）を混合することで、熱膨張率の調整や機械的強度の向上等、特性を改善することが行われる。', explanation: '適当。フィラー混合による特性改善である。' },
      { key: 'D', text: 'エポキシ樹脂は、熱可塑性樹脂であり、一度硬化させた後も、加熱すれば繰り返し軟化・成形することができる材料である。', explanation: '不適当。エポキシ樹脂は熱硬化性樹脂であり、一度硬化させると架橋構造が形成されるため、その後に加熱しても再び軟化・成形することはできない。「熱可塑性樹脂」「繰り返し軟化・成形できる」は誤りである。' },
    ],
